def es_palindromo(texto: str) -> bool:
    s = ''.join(ch.lower() for ch in texto if ch.isalnum())
    return s == s[::-1]

def aplanar(datos):
    def flatten(seq):
        result = []
        for item in seq:
            if isinstance(item, (list, tuple)):
                result.extend(flatten(item))
            else:
                result.append(item)
        return result

    out = []
    for item in datos:
        if isinstance(item, (list, tuple)):
            out.extend(flatten(item))
        else:
            out.append(item)
    return out

